"""Capture and check the TrueType glyphs generated by the actual Pico.
Run under a board lease. Ctrl-] t exports glyph metrics and cache bytes.
--exercise changes face/size live, checks rejection of an oversized cache,
and returns to the initial size. No guest CPU is emulated by this tool.
"""
import argparse,re,time,hashlib
from pathlib import Path
import serial
from PIL import Image

def read_until(s, marker, timeout=4):
 text='';end=time.monotonic()+timeout
 while time.monotonic()<end:
  text+=s.read(s.in_waiting or 1).decode('ascii','replace')
  if marker in text:return text
 raise RuntimeError('missing '+marker+' in '+text[-400:])

def capture(s,out,expect):
 for attempt in range(20):
  s.reset_input_buffer();s.write(b'\x1dt')
  try:text=read_until(s,'END_FONT',1)
  except RuntimeError:
   time.sleep(.15);continue
  break
 else:raise RuntimeError('font did not become ready')
 out.with_suffix('.txt').write_text(text)
 m=re.search(r'(?m)^FONT (\d+) (\d+) (\d+) (\d+)\r?$',text)
 assert m,'missing font header'
 face,size,line,n=map(int,m.groups());assert (face,size)==expect,(face,size,expect)
 rows=[tuple(map(int,m.split())) for m in re.findall(r'(?m)^G ((?:-?\d+ ){6}-?\d+)\r?$',text)]
 assert len(rows)==95, len(rows)
 data=bytes.fromhex(''.join(re.findall(r'(?m)^B ([0-9A-F]+)\r?$',text)))
 assert len(data)==n and n<=4096,(len(data),n)
 palette_match=re.search(r'(?m)^C ((?:\d+ ){15}\d+)\r?$',text)
 palette=list(map(int,palette_match[1].split())) if palette_match else None
 if palette:
  assert len(palette)==16 and palette[0]==0 and palette[-1]==65535
  assert palette==sorted(palette)
  def rgb565(v):
   return ((v>>11)*255//31,((v>>5)&63)*255//63,(v&31)*255//31)
  colours=[rgb565(palette[i*5]) for i in range(4)]
 else:colours=[(i*85,)*3 for i in range(4)]
 glyphs=[]
 for i,w,h,left,top,advance,offset in rows:
  assert i==len(glyphs) and 0<=w<=32 and 0<=h<=32 and 1<=advance<=32
  assert offset+((w+3)//4)*h<=n
  glyph=Image.new('RGB',(w,h))
  for y in range(h):
   for x in range(w):glyph.putpixel((x,y),colours[(data[offset+y*((w+3)//4)+(x>>2)]>>((x&3)*2))&3])
  if i:assert glyph.getbbox(),('empty printable glyph',chr(i+32))
  glyphs.append((glyph,left,top,advance))
 if face==0:assert glyphs[ord('W')-32][3]>glyphs[ord('i')-32][3]
 else:assert len({g[3] for g in glyphs})==1,'monospace advances differ'
 image=Image.new('RGB',(480,line*6))
 samples=['PDP-11 emulator: live TrueType','# ls /usr/bin','ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz','0123456789 !@#$%^&*()[]{}<>?/','The quick brown fox jumps over 0123456789.']
 for y,sample in enumerate(samples):
  xpos=2
  for c in sample:
   glyph,left,top,advance=glyphs[ord(c)-32]
   for gy in range(glyph.height):
    for gx in range(glyph.width):
     px=xpos+left+gx;py=y*line+top+gy
     if 0<=px<image.width and 0<=py<image.height:
      image.putpixel((px,py),max(image.getpixel((px,py)),glyph.getpixel((gx,gy))))
   xpos+=advance
 image.resize((960,image.height*2),Image.Resampling.NEAREST).save(out.with_suffix('.png'))
 digest=hashlib.sha256(data).hexdigest()
 print('BOARD FONT PASS',face,size,n,digest,flush=True)
 return digest

if __name__=='__main__':
 ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--port',required=True);ap.add_argument('--out',type=Path,required=True);ap.add_argument('--size',type=int,default=16);ap.add_argument('--exercise',action='store_true');a=ap.parse_args();a.out.parent.mkdir(parents=True,exist_ok=True)
 with serial.Serial(a.port,115200,timeout=.05,write_timeout=3) as s:
  time.sleep(.2)
  initial=capture(s,a.out,(0,a.size))
  if a.exercise:
   original=initial
   for step in range(abs(a.size-14)):
    s.write(b'\x1d'+(b'-' if a.size>14 else b'+'));time.sleep(.6)
   initial=capture(s,a.out.with_name(a.out.name+'-base14'),(0,14))
   for i,(command,face,size) in enumerate([('+',0,15),('+',0,16),('f',1,16),('-',1,15),('f',0,15),('-',0,14)]):
    s.write(b'\x1d'+command.encode());time.sleep(.6)
    capture(s,a.out.with_name(a.out.name+'-'+str(i)),(face,size))
   s.write(b'\x1d+\x1d+\x1d+\x1d+\x1d+\x1d+')
   time.sleep(.7)
   assert capture(s,a.out.with_name(a.out.name+'-refused'),(0,14))==initial,'refused size damaged previous font'
   s.write(b'\x1ds');stats=read_until(s,'\n===\r\n',3)
   a.out.with_name(a.out.name+'-stats').with_suffix('.txt').write_text(stats)
   assert 'change -5' in stats and '0 dropped' in stats and '0 lost;' in stats,stats
   print('LIVE FONTS PASS: two faces, 14/15/16 pixels, oversized request refused, original glyphs preserved')
   s.write(b'\x1d+');time.sleep(.6)
   capture(s,a.out.with_name(a.out.name+'-clean15'),(0,15))
   s.write(b'\x1d-');time.sleep(.6)
   assert capture(s,a.out.with_name(a.out.name+'-clean14'),(0,14))==initial
   for step in range(abs(a.size-14)):
    s.write(b'\x1d'+(b'+' if a.size>14 else b'-'));time.sleep(.6)
   assert capture(s,a.out.with_name(a.out.name+'-restored'),(0,a.size))==original

